    {trash.length ? <div className="trash-list">{trash.map(e => { const Icon = Glyph[e.kind] || DocGlyph; return <div className="trash-row" key={e.id}><Icon size={18}/><div className="trash-text"><strong>{e.title}</strong><small>{kindName[e.kind]} · {where(e)} · deleted {agoLabel(e.deletedAt)}</small></div><button className="button secondary" onClick={() => perform(() => act({ type: 'trash:restore', value: e.id }))}><RestoreGlyph size={14}/>Restore</button><button className="text-button danger-text" onClick={() => setAsking({ entry: e })}>Delete forever</button></div>; })}</div> : <div className="quiet-placeholder">Trash is empty. Deleted documents, files, folders and agents will show up here.</div>}
    {asking && <ConfirmDelete title={asking.all ? 'Empty Trash?' : 'Delete forever?'} subtitle={asking.all ? `${trash.length} item${trash.length === 1 ? '' : 's'} will be permanently deleted. This cannot be undone.` : `"${asking.entry.title}" will be permanently deleted. This cannot be undone.`} lines={[]} confirmLabel={asking.all ? 'Empty Trash' : 'Delete forever'} onClose={() => setAsking(null)} onConfirm={async () => { await act(asking.all ? { type: 'trash:empty' } : { type: 'trash:purge', value: asking.entry.id }); setAsking(null); }}/>}
