  return <Modal title={project ? 'Project details' : parent ? 'New work folder' : 'New project'} subtitle={parent ? `Inside ${parent.name}. A separate context for this work.` : 'A home for your research and related work.'} onClose={onClose}><form onSubmit={async e => { e.preventDefault(); try { await onSave(project ? { ...project, name, description, agentIds: ids } : { id: uid(), name: name.trim(), description, parentId: parent?.id || null, status: 'active', kpis: [], agentIds: ids, color: 'green', notes: [], files: [], tasks: [], messages: [], edges: [], viewport: { x: 0, y: 0, zoom: 1 } }); } catch (e) { setError(e.message); } }}><label className="form-label">Project name<input required autoComplete="off" placeholder="Name your project or work folder" value={name} onChange={e => setName(e.target.value)}/></label><label className="form-label">What are you exploring?<textarea rows={3} placeholder="A little context for you and your agents…" value={description} onChange={e => setDescription(e.target.value)}/></label><div className="form-label">Choose your team</div><div className="team-list">{agents.map(a => <label key={a.id} className="team-option"><Avatar agent={a} small/><span><strong>{a.name}</strong><small>{a.role}</small></span><input type="checkbox" checked={ids.includes(a.id)} onChange={e => setIds(e.target.checked ? [...ids, a.id] : ids.filter(id => id !== a.id))}/></label>)}</div>{error && <p className="inline-error">{error}</p>}<div className="modal-footer">{project && <button type="button" className="button danger-quiet" onClick={onDelete}><Trash2 size={15}/>Delete</button>}<button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary"><Plus size={15}/>{project ? 'Save changes' : parent ? 'Create folder' : 'Create project'}</button></div></form></Modal>;
