  const needle = filter.toLowerCase(), everything = state.projects.flatMap(p => p.notes.map(n => ({ n, p }))).filter(({ n, p }) => !needle || n.title.toLowerCase().includes(needle) || p.name.toLowerCase().includes(needle) || n.content.toLowerCase().includes(needle));
